INSERT INTO public.site_config ("key", "updated_at", "value") VALUES ('hero_service_text', '2026-08-12T05:40:59.88+00:00', '{"all":{"description":"<p>Professional&nbsp;Embroidery,&nbsp;Patches&nbsp;&amp;&nbsp;Vector&nbsp;Art&nbsp;Services&nbsp;Transform&nbsp;your&nbsp;logos&nbsp;and&nbsp;artwork&nbsp;into&nbsp;professional,&nbsp;production-ready&nbsp;files&nbsp;with&nbsp;our&nbsp;expert&nbsp;Embroidery&nbsp;Digitizing&nbsp;and&nbsp;Custom&nbsp;Patches&nbsp;services,&nbsp;created&nbsp;with&nbsp;precision,&nbsp;clean&nbsp;details,&nbsp;proper&nbsp;sizing,&nbsp;and&nbsp;reliable&nbsp;production&nbsp;in&nbsp;mind.&nbsp;From&nbsp;machine-ready&nbsp;embroidery&nbsp;files&nbsp;for&nbsp;professional&nbsp;embroidery&nbsp;equipment&nbsp;to&nbsp;high-quality&nbsp;custom&nbsp;patches&nbsp;for&nbsp;apparel,&nbsp;uniforms,&nbsp;caps,&nbsp;promotional&nbsp;products,&nbsp;and&nbsp;branded&nbsp;merchandise,&nbsp;we&nbsp;prepare&nbsp;your&nbsp;designs&nbsp;for&nbsp;real-world&nbsp;production.&nbsp;We&nbsp;also&nbsp;provide&nbsp;professional&nbsp;Vector&nbsp;Art&nbsp;to&nbsp;ensure&nbsp;your&nbsp;logos&nbsp;and&nbsp;artwork&nbsp;are&nbsp;clean,&nbsp;scalable,&nbsp;and&nbsp;ready&nbsp;for&nbsp;printing,&nbsp;branding,&nbsp;and&nbsp;other&nbsp;applications.&nbsp;</p>","headline":"<p>Embroidery&nbsp;Digitizing,&nbsp;Custom&nbsp;Patches&nbsp;and&nbsp;Vector&nbsp;Tracing</p>","subtitle":"<p>Commercial&nbsp;Embroidery&nbsp;Digitizing,&nbsp;Scalable&nbsp;Vector&nbsp;Art,&nbsp;Custom&nbsp;Physical&nbsp;Patches</p>"},"embroidery":{"description":"<p>Transform&nbsp;pixelated&nbsp;JPEGs,&nbsp;PNGs,&nbsp;and&nbsp;sketches&nbsp;into&nbsp;100%&nbsp;hand-drawn&nbsp;scalable&nbsp;vector&nbsp;files&nbsp;(.AI,&nbsp;.EPS,&nbsp;.SVG,&nbsp;.PDF,&nbsp;.CDR)&nbsp;with&nbsp;Pantone&nbsp;color&nbsp;separation.&nbsp;Perfect&nbsp;for&nbsp;screen&nbsp;printing,&nbsp;DTG,&nbsp;and&nbsp;large&nbsp;format&nbsp;printing&nbsp;with&nbsp;zero&nbsp;quality&nbsp;loss.</p>","headline":"<p>Vector&nbsp;Art&nbsp;Conversion</p>","subtitle":"<p>Scalable&nbsp;Vector&nbsp;Art&nbsp;Redraw</p>"},"patch":{"description":"<p>High-density&nbsp;embroidered,&nbsp;3D&nbsp;molded&nbsp;waterproof&nbsp;PVC,&nbsp;woven,&nbsp;and&nbsp;laser-engraved&nbsp;leather&nbsp;patches&nbsp;with&nbsp;physical&nbsp;worldwide&nbsp;shipping.&nbsp;Premium&nbsp;quality&nbsp;backings&nbsp;including&nbsp;iron-on,&nbsp;velcro,&nbsp;and&nbsp;peel-and-stick.</p>","headline":"<p>Custom&nbsp;Patches</p>","subtitle":"<p>Custom&nbsp;Physical&nbsp;Patches&nbsp;&amp;&nbsp;Emblems</p>"},"vector-art":{"description":"<p>High-density&nbsp;embroidered,&nbsp;3D&nbsp;molded&nbsp;waterproof&nbsp;PVC,&nbsp;woven,&nbsp;and&nbsp;laser-engraved&nbsp;leather&nbsp;patches&nbsp;with&nbsp;physical&nbsp;worldwide&nbsp;shipping.&nbsp;Premium&nbsp;quality&nbsp;backings&nbsp;including&nbsp;iron-on,&nbsp;velcro,&nbsp;and&nbsp;peel-and-stick.</p>","headline":"<p>Custom&nbsp;Patches</p>","subtitle":"<p>Custom&nbsp;Physical&nbsp;Patches&nbsp;&amp;&nbsp;Emblems</p>"}}'::jsonb) ON CONFLICT DO NOTHING;
