INSERT INTO public.site_config ("key", "updated_at", "value") VALUES ('service_cms', '2026-08-08T05:39:51.31+00:00', '{"embroidery":{"hero":{"badge":"STARTS $10.00","bannerImage":"https://uoflzpbhwhgooeeehnta.supabase.co/storage/v1/object/public/media-gallery/legacy-inline/site-config/service_cms/59f62d4526d504fabfb6e449.jpg","highlight":"100% Guaranteed","primaryCta":"Upload Embroidery Design","secondaryCta":"View Digitizing Rates","subtext":"Convert your logos into clean, production-ready embroidery machine files (.DST, .PES, .EXP, .EMB) engineered for Tajima, Brother, Melco & Barudan multi-head machines with zero thread breaks.","title":"Commercial Embroidery Digitizing","trustPoints":[{"sub":"Master digitizers, zero auto-trace","title":"100% Manual Digitizing"},{"sub":"100% satisfaction guaranteed","title":"Free Revisions Included"},{"sub":"DST, PES, EXP, EMB, JEF","title":"Machine-Ready Formats"},{"sub":"24/7 express rush processing","title":"Super Fast 4-12 Hrs Delivery"}]},"showcase":{"samples":[{"category":"Left Chest","colors":"5 Madeira Colors","fabric":"Pique Cotton Polo","id":"emb-s1","image":"https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?auto=format&fit=crop&w=800&q=80","stitches":"12,450 Stitches","title":"Golden Eagle Sports Polo"},{"category":"3D Puff Cap","colors":"2 Colors (3mm Foam)","fabric":"Structured Wool Cap","id":"emb-s2","image":"https://images.unsplash.com/photo-1588850561407-ed78c282e89b?auto=format&fit=crop&w=800&q=80","stitches":"15,800 Stitches","title":"Tactical Flexfit Cap Front"},{"category":"Jacket Back","colors":"8 Madeira Colors","fabric":"Heavy Leather & Canvas","id":"emb-s3","image":"https://images.unsplash.com/photo-1521572267360-ee0c2909d518?auto=format&fit=crop&w=800&q=80","stitches":"48,200 Stitches","title":"Heritage Apparel Jacket Crest"}],"subtext":"Real commercial embroidery sew-outs produced on Tajima, Brother, and Barudan multi-head industrial machines.","title":"Embroidery Sew-Outs & Stitch Quality Showcase"},"workflow":{"steps":[{"desc":"Submit your logo file and specify target fabric type (polo, cap, hoodie) and required dimensions.","step":"01","title":"Upload Raster / Vector Logo"},{"desc":"Master digitizers set Wilcom underlay density, satin stitch directions, and fabric pull compensation.","step":"02","title":"Manual Pathing & Density Mapping"},{"desc":"Every machine file undergoes pathing simulation to guarantee zero thread trims and zero needle breaks.","step":"03","title":"Virtual Stitch Simulation & Testing"},{"desc":"Download production-ready machine files (.DST, .PES, .EMB) with 100% free unlimited revisions.","step":"04","title":"Instant Download & Free Revisions"}],"subtext":"From initial logo upload to machine-ready stitch file delivery in 4 simple steps.","title":"How It Works: Embroidery Digitizing Workflow"}},"patch":{"hero":{"badge":"STARTS $1.50 / PATCH","highlight":"Physical Shipping","primaryCta":"Order Custom Patches","secondaryCta":"Explore Patch Tiers","subtext":"Order high-density embroidered patches, 3D molded waterproof PVC emblems, woven labels, and genuine laser-engraved leather patches with physical shipping worldwide.","title":"Physical Custom Patches & Emblems","trustPoints":[{"sub":"Hook & loop, heat seal or sew-on","title":"Velcro & Iron-On Backing"},{"sub":"Overlock edges & die-cut shapes","title":"Classic Merrowed Borders"},{"sub":"High-durability tactical rubber","title":"Waterproof 3D Molded PVC"},{"sub":"Express physical delivery","title":"3-5 Days Production"}]},"showcase":{"samples":[{"category":"Overlock Edge","colors":"Velcro Backing","fabric":"Heavy Duty Felt","id":"pat-s1","image":"https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&w=800&q=80","stitches":"High Density Rayon","title":"Tactical Merrowed Embroidered Patch"},{"category":"Tactical PVC","colors":"Hook & Loop Backing","fabric":"Tactical Outerwear","id":"pat-s2","image":"https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?auto=format&fit=crop&w=800&q=80","stitches":"Waterproof Rubber","title":"3D Molded Rubber PVC Patch"},{"category":"Real Leather","colors":"Heat Seal Iron-On","fabric":"Denim & Headwear","id":"pat-s3","image":"https://images.unsplash.com/photo-1588850561407-ed78c282e89b?auto=format&fit=crop&w=800&q=80","stitches":"Engraved Leather","title":"Laser Debossed Genuine Leather Patch"}],"subtext":"Custom embroidered, woven, PVC rubber, and genuine leather emblems delivered nationwide.","title":"Physical Custom Patches & Goods Showcase"},"workflow":{"steps":[{"desc":"Upload your artwork and choose patch material (Embroidered, Woven, PVC, Leather), backing, and border.","step":"01","title":"Artwork Submission & Specs"},{"desc":"Receive a high-resolution 1:1 digital mockup & physical sample proof for final approval before mass production.","step":"02","title":"Digital Proof & Approval"},{"desc":"High-density embroidery, fine woven thread weaving, or 3D waterproof PVC vulcanization.","step":"03","title":"Precision Stitching & Molding"},{"desc":"Every emblem undergoes strict quality inspection before express physical shipping worldwide.","step":"04","title":"Quality Check & Express Shipping"}],"subtext":"Crafting premium physical emblems from digital proofing to doorstep delivery.","title":"How It Works: Custom Patches Production Workflow"}},"vector":{"hero":{"badge":"STARTS $15.00 FLAT","highlight":"Hand-Traced Vector","primaryCta":"Upload Artwork for Vectoring","secondaryCta":"View Vector Rates","subtext":"Transform pixelated JPEGs, PNGs, and hand sketches into 100% resolution-independent vector graphics (.AI, .EPS, .SVG, .PDF) with Pantone spot color separation.","title":"Raster to Scalable Vector Redraw","trustPoints":[{"sub":"Clean vectors for printing & cutting","title":"100% Hand-Drawn Node Paths"},{"sub":"Screen printing & vinyl cut ready","title":"Pantone Spot Color Separation"},{"sub":"AI, EPS, SVG, PDF, CDR","title":"Master Source Files Included"},{"sub":"Same-day vector delivery","title":"6-12 Hrs Turnaround"}]},"showcase":{"samples":[{"category":"Spot Color Sep","colors":"4 Pantone Spot Colors","fabric":"Screen Printing & Cutters","id":"vec-s1","image":"https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=800&q=80","stitches":"N/A (Scalable Vector)","title":"Vintage Skull & Rose Vector"},{"category":"Hand-Drawn Vector","colors":"3 Screen Colors","fabric":"Vinyl & Apparel Print","id":"vec-s2","image":"https://images.unsplash.com/photo-1579783902614-a3fb3927b675?auto=format&fit=crop&w=800&q=80","stitches":"N/A (Scalable Vector)","title":"Wildcat Athletic Team Mascot"},{"category":"Clean AI & SVG","colors":"Full CMYK Vector","fabric":"Large Format Banners","id":"vec-s3","image":"https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&w=800&q=80","stitches":"N/A (Scalable Vector)","title":"Corporate Shield & Crest Redraw"}],"subtext":"Low-res raster JPEGs converted into resolution-independent Adobe Illustrator vector node paths.","title":"Vector Art Redrawing & Separation Showcase"},"workflow":{"steps":[{"desc":"Upload your pixelated JPEG, PNG, or hand sketch with target printing specifications.","step":"01","title":"Upload Low-Res Image or Sketch"},{"desc":"Vector artists redraw your logo node-by-node in Adobe Illustrator — zero auto-tracing distortion.","step":"02","title":"Manual Pen-Tool Vector Tracing"},{"desc":"Clean Pantone spot color layer separation ready for screen printing films and vinyl plotters.","step":"03","title":"Color Separation & Scale Adjustment"},{"desc":"Download resolution-independent master vector source files (.AI, .EPS, .SVG, .PDF).","step":"04","title":"Instant Vector Delivery"}],"subtext":"Pixel-perfect node tracing and color separation for print and vinyl cutting.","title":"How It Works: Vector Art Conversion Workflow"}}}'::jsonb) ON CONFLICT DO NOTHING;
