INSERT INTO public.site_config ("key", "updated_at", "value") VALUES ('hero_slides', '2026-09-28T02:21:12.346+00:00', '[{"afterImg":"","badge":"Complete Studio Capabilities","banner_image":"","description":"Professional Embroidery Digitizing, Vector Artwork, and Custom Patches all in one place.\n\nWe convert your artwork into machine-ready DST, PES, and EMB files, create clean AI, EPS, and SVG vector artwork, and produce custom patches with Velcro or Iron-On backing with free shipping straight to your doorstep.","features":["Embroidery Digitizing: Convert your logos into DST, PES, JEF, VP3 and EMB files","Vector Tracing: Convert low-resolution into clean, scalable AI, EPS, and SVG files.","Custom Physical Patches:  Create high-quality custom patches, including free shipping."],"highlight":"Three Master Services. Factory-Grade Precision. 4–12 Hr Delivery.","id":"all","previewTitle":"All Studio Production Results","primary_btn_action":"#pricing","primary_cta":"Get Started Now","secondary_btn_action":"/pricing","secondary_cta":"Explore Packages","serviceKey":"all","showcase_images":[],"slideshow_interval":3,"stats":[{"label":"Clients","value":"1,210+"},{"label":"Countries","value":"45+"},{"label":"Express","value":"4-Hr"},{"label":"Guaranteed","value":"100%"}],"title":"Embroidery Digitizing, Scalable Vector Art & Custom Patches","updated_at":"2026-09-05T16:50:55.604Z"},{"afterImg":"","badge":"Custom Manufactured Emblems","banner_image":"","description":"Custom manufactured physical patches for uniforms, tactical gear, hats, and apparel brands. Available with Velcro hook & loop, iron-on, or adhesive backings with free digital proofs before production.","features":["Custom Embroidered, High-Density Woven & 3D Rubber PVC","Military-Grade Velcro, Heat-Seal Iron-On & Peel Backings","Free 12-Hour Digital Proof & Doorstep Worldwide Shipping","Quantity Tiers: Sample (10-50 pcs), Production (100-500 pcs), Bulk ($1.50/pc)"],"highlight":"Embroidered, Woven & 3D Molded PVC. Doorstep Delivery.","id":"patches","previewTitle":"Artwork to Physical Manufactured Patch","primary_btn_action":"/order","primary_cta":"Order Custom Patches","secondary_btn_action":"/custom-patches","secondary_cta":"Get Free Patch Proof","serviceKey":"patches","showcase_images":[],"slideshow_interval":5,"stats":[{"label":"Low MOQ","value":"10 Pcs"},{"label":"Free Proof","value":"12-Hr"},{"label":"Production","value":"3-5 Day"},{"label":"Doorstep Delivery","value":"Global"}],"title":"Premium Physical Custom Patches","updated_at":"2026-09-05T16:50:20.969Z"},{"afterImg":"https://uoflzpbhwhgooeeehnta.supabase.co/storage/v1/object/public/portfolio-images/showcase-gallery/e82803b4-1dca-4138-bc49-892f57095c9a.PNG","badge":"Factory-Grade Machine Digitizing","banner_image":"https://uoflzpbhwhgooeeehnta.supabase.co/storage/v1/object/public/portfolio-images/showcase-gallery/e82803b4-1dca-4138-bc49-892f57095c9a.PNG","description":"Our expert digitizers transform your logos and artwork into high-quality, machine-ready embroidery files, including DST, PES, JEF, XXX, VP3, EXP, and more. We prioritize customer satisfaction and provide fast, reliable delivery with professional-quality results.","features":["100% Manual Digitizing (Zero Auto-Trace Shortcuts)","All Machine Formats: Tajima (.DST), Wilcom (.EMB), Brother (.PES)","Guaranteed Zero Thread Breaks & Free Unlimited Production Edits"],"highlight":"Zero Thread Breaks. Calculated Pull Compensation. Press Ready.","id":"embroidery","previewTitle":"Raw Art to High-Density Sew-Out","primary_btn_action":"/order","primary_cta":"Order Embroidery Digitizing","secondary_btn_action":"/services/embroidery-digitizing","secondary_cta":"View Embroidery Packages","serviceKey":"embroidery","showcase_images":[{"after_image_url":"https://uoflzpbhwhgooeeehnta.supabase.co/storage/v1/object/public/portfolio-images/showcase-gallery/e82803b4-1dca-4138-bc49-892f57095c9a.PNG","display_order":1,"id":"img-1786803116496","image_url":"https://uoflzpbhwhgooeeehnta