INSERT INTO public.faqs ("answer", "category", "created_at", "id", "question", "sort_order") VALUES ('Our standard turnaround time is 12 to 24 hours. For urgent projects, we offer a Rush Service that guarantees delivery within 4 to 8 hours for a small additional fee.', 'general', '2026-08-09T14:58:56.700701+00:00', 'f1', 'What is your turnaround time?', 1) ON CONFLICT DO NOTHING;
INSERT INTO public.faqs ("answer", "category", "created_at", "id", "question", "sort_order") VALUES ('Yes! We offer 100% free unlimited revisions on all digitizing and vector orders until you are completely satisfied with the result.', 'general', '2026-08-09T14:58:56.700701+00:00', 'f2', 'Do you offer free revisions?', 2) ON CONFLICT DO NOTHING;
INSERT INTO public.faqs ("answer", "category", "created_at", "id", "question", "sort_order") VALUES ('We provide all standard commercial and home machine formats including Tajima (.DST), Brother (.PES), Melco (.EXP), Janome (.JEF), Husqvarna (.HUS), and native Wilcom (.EMB).', 'embroidery', '2026-08-09T14:58:56.700701+00:00', 'f3', 'What embroidery machine formats do you provide?', 1) ON CONFLICT DO NOTHING;
INSERT INTO public.faqs ("answer", "category", "created_at", "id", "question", "sort_order") VALUES ('Never. Every single design is 100% manually digitized by our master digitizers using Wilcom software to ensure optimal pathing, density, and zero thread breaks.', 'embroidery', '2026-08-09T14:58:56.700701+00:00', 'f4', 'Do you use auto-digitizing software?', 2) ON CONFLICT DO NOTHING;
INSERT INTO public.faqs ("answer", "category", "created_at", "id", "question", "sort_order") VALUES ('You will receive a complete master file package containing Adobe Illustrator (.AI), .EPS, .SVG, and a high-resolution .PDF.', 'vector', '2026-08-09T14:58:56.700701+00:00', 'f5', 'What file formats will I receive for vector art?', 1) ON CONFLICT DO NOTHING;
INSERT INTO public.faqs ("answer", "category", "created_at", "id", "question", "sort_order") VALUES ('Absolutely. We ensure all vector files are perfectly node-traced with proper Pantone spot color separation, making them 100% ready for screen printing and vinyl cutting.', 'vector', '2026-08-09T14:58:56.700701+00:00', 'f6', 'Are your vectors ready for screen printing?', 2) ON CONFLICT DO NOTHING;
INSERT INTO public.faqs ("answer", "category", "created_at", "id", "question", "sort_order") VALUES ('Our minimum order quantity for custom physical patches (embroidered, PVC, woven, or leather) is 50 pieces.', 'patches', '2026-08-09T14:58:56.700701+00:00', 'f7', 'What is the minimum order quantity for physical patches?', 1) ON CONFLICT DO NOTHING;
INSERT INTO public.faqs ("answer", "category", "created_at", "id", "question", "sort_order") VALUES ('We offer Iron-On (Heat Seal), Velcro (Hook & Loop), and standard Sew-On backings for all our patch types.', 'patches', '2026-08-09T14:58:56.700701+00:00', 'f8', 'What backing options do you offer for patches?', 2) ON CONFLICT DO NOTHING;
INSERT INTO public.testimonials ("avatar", "comment", "company", "created_at", "id", "name", "rating", "role", "service_category", "sort_order") VALUES (NULL, 'BDigitizing has transformed our workflow. Their embroidery files sew out flawlessly every single time. We threw our most complex jacket back at them, and it was perfect on the first run.', 'Elite Apparel', '2026-08-09T14:58:56.700701+00:00', 't1', 'Sarah Jenkins', 5, 'Production Manager', 'embroidery', 1) ON CONFLICT DO NOTHING;
INSERT INTO public.testimonials ("avatar", "comment", "company", "created_at", "id", "name", "rating", "role", "service_category", "sort_order") VALUES (NULL, 'The vector art team here is incredible. They take our clients'' blurry, pixelated logos and turn them into perfect print-ready vectors in hours. It saves us so much time.', 'Chen Screen Printing', '2026-08-09T14:58:56.700701+00:00', 't2', 'Marcus Chen', 5, 'Owner', 'vector', 2) ON CONFLICT DO NOTHING;
INSERT INTO public.testimonials ("avatar", "comment", "company", "created_at", "id", "name", "rating", "role", "service_category", "sort_order") VALUES (NULL, 'We order thousands of PVC patches monthly. The quality, durability, and 3D molding detail from BDigitizing is unmatched. Plus, their worldwide shipping is surprisingly fast.', 'Tactical Gear Co', '2026-08-09T14:58:56.700701+00:00', 't3', 'David Rossi', 5, 'Director', 'patches', 3) ON CONFLICT DO NOTHING;
INSERT INTO public.testimonials ("avatar", "comment", "company", "created_at", "id", "name", "rating", "role", "service_category", "sort_order") VALUES (NULL, 'Having one partner for digitizing, vectoring, and patches is a game changer. The 24/7 support is real – I''ve had revisions done at 2 AM on a Sunday. Highly recommended.', 'Torres Designs', '2026-08-09T14:58:56.700701+00:00', 't4', 'Emily Torres', 5, 'Creative Director', 'general', 4) ON CONFLICT DO NOTHING;
